/* Homepage Deduções - current-rule search and the personal lens.
 *
 * NO RATE OR CEILING IS WRITTEN IN THIS FILE (ch.17 responsibilities). Everything numeric is read
 * from the artefacts the repository already publishes and cross-checks in CI:
 *     audit-manifest.json   what tool.js actually computes with, generated by make-audit.mjs
 *     audit-freshness.json  whether the article still says so
 *
 * The static table in deducoes.html stays hand-maintained ON PURPOSE. It is the third independent
 * source in test-deducoes-sync.js's three-way agreement (page == CEIL == snapshots); generating it
 * from the manifest would turn the cross-check into a comparison of a file with its own derivative
 * and quietly retire the invariant. It is also the no-JS fallback.
 */
(function () {
  "use strict";

  var form = document.getElementById("ded-form");
  if (!form) return;

  var q = document.getElementById("db-q");
  var out = document.getElementById("db-result");
  var list = document.getElementById("db-res-list");
  var resTitle = document.getElementById("db-res-title");
  var lensGeral = document.getElementById("lens-geral");
  var lensMeu = document.getElementById("lens-meu");
  var lensNote = document.getElementById("lens-note");
  var locked = document.getElementById("personal-locked");
  var view = document.getElementById("personal-view");

  var DATA = null;

  function esc(s) {
    return String(s == null ? "" : s).replace(/[<>&"]/g, function (c) {
      return { "<": "&lt;", ">": "&gt;", "&": "&amp;", '"': "&quot;" }[c];
    });
  }

  function load() {
    if (DATA) return Promise.resolve(DATA);
    function json(url, optional) {
      return fetch(url, { cache: "no-store" }).then(function (r) {
        if (!r.ok) throw new Error(url + " devolveu HTTP " + r.status);
        return r.json();
      }).catch(function (error) {
        if (optional) return null;
        throw error;
      });
    }
    return Promise.all([
      json("/audit-manifest.json", false),
      json("/audit-freshness.json", true)
    ]).then(function (a) {
      DATA = { audit: a[0], fresh: a[1] };
      return DATA;
    });
  }

  form.addEventListener("submit", function (e) {
    e.preventDefault();
    var term = q.value.trim().toLowerCase();
    load().then(function (d) {
      var rows = (d.audit && d.audit.rows) || [];
      var fmap = {};
      if (d.fresh && d.fresh.sources) d.fresh.sources.forEach(function (s) { fmap[s.id] = s.status; });

      var hits = rows.filter(function (r) {
        if (!term) return true;
        return ((r.sector || "") + " " + (r.code || "") + " " + (r.article || "")).toLowerCase()
          .indexOf(term) !== -1;
      });

      out.hidden = false;
      if (!hits.length) {
        list.innerHTML = '<p class="note"><svg aria-hidden="true" focusable="false">' +
          '<use href="/assets/icons.svg#fb-info"></use></svg><span>Sem correspondencia. ' +
          'Ve a tabela completa abaixo ou abre a <a href="/auditoria">matriz gerada</a>.</span></p>';
      } else {
        list.innerHTML = hits.map(function (r) {
          var st = fmap[r.source_id];
          var conf = st === "OK"
            ? '<span class="state state-ok"><svg aria-hidden="true" focusable="false">' +
              '<use href="/assets/icons.svg#fb-check"></use></svg>Conferido na fonte</span>'
            : '<span class="state state-unknown"><svg aria-hidden="true" focusable="false">' +
              '<use href="/assets/icons.svg#fb-circulo"></use></svg>Por confirmar</span>';
          return '<article class="db-hit"><h4>' + esc(r.code) + " &middot; " + esc(r.sector) + "</h4>" +
            '<p class="db-meta">' +
              '<span class="num">' + esc(r.rate) + " " + esc(r.base) + "</span>" +
              (r.ceiling_eur != null ? '<span class="num">teto ' + esc(r.ceiling_eur) + " &euro;</span>" : "") +
              (r.article ? '<span class="mono">' + esc(r.article) + "</span>" : "") +
              conf +
            "</p>" +
            (r.source_url ? '<p><a href="' + esc(r.source_url) + '" target="_blank" rel="noopener">Abrir a fonte oficial</a></p>' : "") +
            "</article>";
        }).join("");
      }
      resTitle.focus();
    }).catch(function () {
      out.hidden = false;
      list.innerHTML = '<p class="fb-note fb-note-bad"><svg aria-hidden="true" focusable="false">' +
        '<use href="/assets/icons.svg#fb-aviso"></use></svg><span>Não foi possível carregar a matriz ' +
        'auditada. A tabela estática abaixo continua disponível; tenta novamente ou abre a ' +
        '<a href="/auditoria">auditoria completa</a>.</span></p>';
      resTitle.focus();
    });
  });

  /* ---------------------------------------------------------------- the personal lens
   * Reads ONLY what perfil.html already stored in this browser. If there is nothing, the lens
   * stays locked and says so. It never renders placeholder figures in the personal panel. */
  var contract = window.FBProfileContract;
  var profile = contract ? contract.read(localStorage) : null;

  function money(value) {
    return Number(value).toLocaleString("pt-PT", { style: "currency", currency: "EUR" });
  }

  function renderPersonal(profile) {
    if (!view || !profile) return;
    var parts = profile.partitions || {};
    var done = contract ? contract.completedPartitions(profile) : [];
    var efatura = parts.efatura && parts.efatura.status === "done" ? parts.efatura.data : null;
    var recibos = parts.recibos && parts.recibos.status === "done" ? parts.recibos.data : null;
    var official = recibos && recibos.deducoesOficiais;
    var rows = [];

    if (official && Number.isFinite(Number(official.total))) {
      rows.push('<div class="personal-row"><div><b>Deduções à coleta' +
        (official.ano ? " · " + esc(official.ano) : "") + '</b>' +
        '<span>Valor oficial calculado pela AT, por titular.</span></div>' +
        '<strong>' + esc(money(official.total)) + '</strong></div>');
    }

    if (efatura && Number.isFinite(Number(efatura.porClassificar))) {
      rows.push('<div class="personal-row"><div><b>Faturas por classificar' +
        (efatura.ano ? " · " + esc(efatura.ano) : "") + '</b>' +
        '<span>Leitura do e-Fatura nesta sessão.</span></div>' +
        '<strong>' + esc(efatura.porClassificar) + '</strong></div>');
    }

    (efatura && Array.isArray(efatura.reAudit) ? efatura.reAudit : []).forEach(function (item) {
      var amount = item && item.recuperavelAconselhado;
      if (!(Number(amount) > 0)) return;
      rows.push('<div class="personal-row personal-indicator"><div><b>Possível recuperação · ' +
        esc(item.ano || "ano anterior") + '</b><span>Indicador pelo setor principal do comerciante; ' +
        'confirma o prazo e cada fatura antes de corrigir.</span></div><strong>' +
        esc(money(amount)) + '</strong></div>');
    });

    view.innerHTML = '<p class="personal-origin mono">' + done.length +
      (done.length === 1 ? " fonte carregada" : " fontes carregadas") +
      ' neste navegador</p>' +
      (rows.length ? '<div class="personal-rows">' + rows.join("") + '</div>' :
        '<p class="fb-note"><svg aria-hidden="true" focusable="false"><use href="/assets/icons.svg#fb-info"></use></svg>' +
        '<span>O perfil existe, mas ainda não contém uma leitura do e-Fatura nem as deduções oficiais. ' +
        '<a href="/perfil">Continua a recolha em “A minha situação”</a>.</span></p>') +
      '<p class="personal-caveat">Ausência de dados não significa zero. Só aparecem valores realmente ' +
      'lidos e ainda guardados neste navegador.</p>';
  }

  if (!profile) {
    lensMeu.disabled = true;
    lensMeu.setAttribute("aria-disabled", "true");
  } else {
    lensNote.textContent = "Os teus dados estão neste navegador e expiram no fim do dia.";
    if (locked) locked.hidden = true;
    renderPersonal(profile);
  }

  function setLens(personal) {
    lensGeral.setAttribute("aria-pressed", personal ? "false" : "true");
    lensMeu.setAttribute("aria-pressed", personal ? "true" : "false");
    if (locked) locked.hidden = !!profile || !personal;
    if (view) view.hidden = !(personal && profile);
  }

  function goTo(id) {
    var target = document.getElementById(id);
    if (!target) return;
    var reduce = false;
    try { reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches; } catch (e) {}
    try { target.scrollIntoView({ behavior: reduce ? "auto" : "smooth", block: "start" }); }
    catch (e) { target.scrollIntoView(); }
    try { target.focus({ preventScroll: true }); } catch (e) { target.focus(); }
  }

  lensGeral.addEventListener("click", function () { setLens(false); goTo("setores"); });
  lensMeu.addEventListener("click", function () {
    if (!profile) {
      // Explain, do not silently do nothing.
      lensNote.textContent = "Ainda nao ha uma situacao carregada neste navegador. Abre “A minha situacao” primeiro.";
      lensNote.classList.add("state-warn");
      return;
    }
    setLens(true);
    goTo("minha-h");
  });
})();
